BUTTON_NAMES = {'Clone Slide': 'One Slide', 'Slide Bevel': 'Two Slide', 'Floater': 'Floater Liner'}
_CACHE={}
def icon(name):
 if name in _CACHE:return _CACHE[name]
 result=QtGui.QIcon()
 for state,color in ((QtGui.QIcon.Off,'#d7a47c'),(QtGui.QIcon.On,'#e3b38c')):
  body=PATHS[name].replace('currentColor',color)
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><g fill="none" stroke="{color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg>'
  pix=QtGui.QPixmap(64,64);pix.fill(QtCore.Qt.transparent);p=QtGui.QPainter(pix)
  QtSvg.QSvgRenderer(QtCore.QByteArray(svg.encode())).render(p);p.end()
  result.addPixmap(pix,QtGui.QIcon.Normal,state)
 _CACHE[name]=result;return result

def group_tools(window,data):
 layout=window.layout();buttons={w.text():w for w in window.findChildren(QtWidgets.QPushButton) if w.text() in PATHS}
 assert set(buttons)=={x[0] for x in data},'A toolbox button is missing'
 container=QtWidgets.QWidget(window);outer=QtWidgets.QVBoxLayout(container)
 outer.setContentsMargins(0,0,0,0);outer.setSpacing(8);outer.setAlignment(QtCore.Qt.AlignTop)
 window.tool_groups={}
 for name,labels in GROUPS.items():
  head=QtWidgets.QToolButton(container);head.setText(name.upper());head.setCheckable(True);head.setChecked(True)
  head.setToolButtonStyle(QtCore.Qt.ToolButtonTextBesideIcon);head.setArrowType(QtCore.Qt.DownArrow)
  head.setStyleSheet('QToolButton{background:transparent;border:0;color:#92a3a6;font-size:10px;font-weight:600;padding:0;min-height:18px;text-align:left;}')
  head.setSizePolicy(QtWidgets.QSizePolicy.Expanding,QtWidgets.QSizePolicy.Fixed);outer.addWidget(head)
  body=QtWidgets.QWidget(container);grid=QtWidgets.QGridLayout(body);grid.setContentsMargins(0,0,0,0);grid.setSpacing(5)
  for i,label in enumerate(labels):
   btn=buttons[label];layout.removeWidget(btn);grid.addWidget(btn,i//2,i%2)
   btn.setText(BUTTON_NAMES.get(label, label))
  grid.setColumnStretch(0,1);grid.setColumnStretch(1,1);outer.addWidget(body)
  def toggle(checked,body=body,head=head):
   body.setVisible(checked);head.setArrowType(QtCore.Qt.DownArrow if checked else QtCore.Qt.RightArrow)
  head.toggled.connect(toggle);window.tool_groups[name]=(head,body)
 layout.addWidget(container,1,0,(len(data)+1)//2,2);window.tool_container=container

